using Godot;
using System;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
 HFlowContainer directiveRetryBar=null!;OptionButton directiveOriginalChoice=null!;EntityId[] directiveOriginalIds=[];string? selectedDirectiveOriginal;
 static string DirectiveKindName(UnitDirectiveKind kind)=>kind switch{UnitDirectiveKind.Move=>"移動",UnitDirectiveKind.Hold=>"待機",_=>"帰還"};
 NewMilitaryRequest[] SentDirectiveRows(ContractWorld w)=>w.NewMilitary==null||selectedKnownTarget==null?[]:w.NewMilitary.Requests.Where(q=>q.Revision>=NewGameMilitary.Cases(w).Last().Revision&&q.Input.Action==NewMilitaryAction.SendUnitDirective&&q.Input.Directive!.Known.Unit.Value==selectedKnownTarget).ToArray();
 void BuildDirectiveRetryUI(VBoxContainer root){directiveRetryBar=new();root.AddChild(directiveRetryBar);directiveRetryBar.AddChild(new Label{Text="対象の発送済み指示"});directiveOriginalChoice=new(){CustomMinimumSize=new(350,0)};directiveRetryBar.AddChild(directiveOriginalChoice);directiveOriginalChoice.ItemSelected+=n=>{selectedDirectiveOriginal=directiveOriginalIds[(int)n].Value;Refresh();};Add(directiveRetryBar,"unit-directive-retry","選んだ原本を再送",RetrySelectedDirective);buttons["unit-directive-retry"].TooltipText="不達報告を受け取り、同じ隊の所在地を確認した時に再送できます。内容と元の期限は維持します。";BuildDirectiveHoldingUI();BuildDirectiveCancelUI(root);BuildDirectiveCancelRetryUI(root);}
 void RefreshDirectiveRetry(){if(directiveRetryBar==null)return;var w=Snapshot();var rows=SentDirectiveRows(w);var ids=rows.Select(q=>q.Input.Id).ToArray();directiveRetryBar.Visible=NewGameMilitary.RecognitionEnabled(w)&&ids.Length>0;if(!ids.SequenceEqual(directiveOriginalIds)){directiveOriginalChoice.Clear();directiveOriginalIds=ids;foreach(var q in rows){string expiry=q.Input.DeliverBy is {} until?"／期限：開始"+until+"秒":"";directiveOriginalChoice.AddItem(DirectiveKindName(q.Input.Directive!.Kind)+"指示／開始"+q.At+"秒"+expiry);}}if(selectedDirectiveOriginal==null||!ids.Any(i=>i.Value==selectedDirectiveOriginal))selectedDirectiveOriginal=ids.LastOrDefault().Value;int index=Array.FindIndex(ids,i=>i.Value==selectedDirectiveOriginal);if(index>=0)directiveOriginalChoice.Select(index);buttons["unit-directive-retry"].Disabled=index<0||!NewGameMilitary.UnitDirectiveRetryAllowed(w,ids[index]);RefreshDirectiveHolding();RefreshDirectiveCancel();RefreshDirectiveCancelRetry();}
 void RetrySelectedDirective(){var w=Snapshot();var row=SentDirectiveRows(w).SingleOrDefault(q=>q.Input.Id.Value==selectedDirectiveOriginal);if(row==null)return;var known=NewGameMilitary.SelectKnownTarget(w,row.Input.Directive!.Known.Unit);if(known==null)return;Submit(Session.DecideNewMilitary(new NewMilitaryInput(new("request:unit-directive-retry-ui/"+Session.Revision),NewMilitaryAction.RetryUnitDirective){DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,row.Input.Id,known),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},Session.PlayerControl,Session.Revision));}
 object? DirectiveRetryPose()=>directiveRetryBar==null?null:new{Selected=selectedDirectiveOriginal,Choices=directiveOriginalIds,directiveRetryBar.Visible,Enabled=!buttons["unit-directive-retry"].Disabled,Text=directiveOriginalChoice.Selected>=0?directiveOriginalChoice.GetItemText(directiveOriginalChoice.Selected):"",CancelRetry=DirectiveCancelRetryPose(),Cancellation=DirectiveCancelPose(),Holding=DirectiveHoldingPose()};
 internal string? SelectedDirectiveOriginalId=>selectedDirectiveOriginal;
 internal void SelectDirectiveOriginal(EntityId id){Refresh();int index=Array.IndexOf(directiveOriginalIds,id);if(index<0)throw new InvalidOperationException("Unsent or foreign original cannot be selected");directiveOriginalChoice.Select(index);directiveOriginalChoice.EmitSignal(OptionButton.SignalName.ItemSelected,index);}
}
